4. Concrete comparison
Without select
</> TypeScript
function UserName() {
const { data } = useQuery({
queryKey: [‘user’],
queryFn: fetchUser,
})
return <div>{data?.name}</div>
}

With select
</> TypeScript
function UserName() {
const { data: name } = useQuery({
queryKey: [‘user’],
queryFn: fetchUser,
select: (user) => user.name,
})
return <div>{name}</div>
}
Same backend change:
</> TypeScript
{ name: ‘Alice’, email: ‘a@mail.com' }

16. select + child components
A powerful pattern is:
e parent subscribes to IDs
e children subscribe to details separately
</> TypeScript
function TodoList() {
const { data: todoIds } = useQuery({
queryKey: [‘todos'],
queryFn: fetchTodos,
select: (todos) => todos.map((t) => t-.id),
})
return (
<ul>
{todoIds?.map((id) => (
<TodoItem key={id} id={id} />
))}
</ul>
)
}
NY

function TodoItem({ id }: { id: string }) {
const { data: todo } = useQuery({
queryKey: [‘todo', id],
queryFn: () => fetchTodo(id),
})
return <1li>{todo?.text}</1li>
}
This makes updates more local.
